// ===== p349 : l'aquarelle du camp marron (fournie par Paris) : en fond de « Se mêler au camp — dans la peau de qui ? »,
// et en tableau d'entrée quand on plonge dans un camp. Cases sur pilotis en planches et paille, calebasses, nattes, jardin de
// patates et de songes, le feu au milieu, les remparts du cirque autour. =====
const CAMP349='data:image/jpeg;base64,';
setInterval(()=>{try{const d=document.getElementById('peau320');if(d&&!d.dataset.f349){d.dataset.f349=1;d.style.background='linear-gradient(rgba(20,14,8,.78),rgba(20,14,8,.93)),url('+CAMP349+') center/cover';d.style.width='min(680px,calc(100% - 32px))';
 const t=document.createElement('div');t.style.cssText='height:150px;margin:-14px -16px 10px;border-radius:12px 12px 0 0;background:url('+CAMP349+') center 40%/cover;box-shadow:inset 0 -30px 30px rgba(20,14,8,.9)';d.prepend(t)}}catch(e){}},400);
